import { cacheTag, cacheLife } from "next/cache"

export interface Post {
  id: number
  title: string
  content: string
}

const posts: Post[] = [
  { id: 1, title: "First Post", content: "Hello world!" },
]

let nextId = 2

export async function createPost(title: string, content: string): Promise<Post> {
  const post: Post = { id: nextId++, title, content }
  posts.push(post)
  return post
}

export async function getCachedPosts(): Promise<Post[]> {
  "use cache"
  cacheTag("posts")
  cacheLife("hours")
  return getPosts()
}

async function getPosts(): Promise<Post[]> {
  return [...posts]
}

